"Частное умножаем на делитель и прибавляем остаток. 99 · 10 = 990, 990 + 8 = 998.": "Wir multiplizieren den Quotienten mit dem Divisor und addieren den Rest. 99 · 10 = 990, 990 + 8 = 998.",
"V = 5 · 8 · 3 = 120 дм³. 1 дм³ вмещает 1 л воды, значит в аквариум входит 120 л.": "V = 5 · 8 · 3 = 120 dm³. In 1 dm³ passt 1 l Wasser, also fasst das Aquarium 120 l.",
"Неизвестное вычитаемое равно уменьшаемому без разности: 50 000 − 18 000 = 32 000.": "Der unbekannte Subtrahend ist gleich dem Minuenden ohne die Differenz: 50 000 − 18 000 = 32 000.",
"Привет! Это Барсик. Сегодня находим доли часа, суток и года. Нажимай на карточки.": "Hallo! Ich bin Barsik. Heute finden wir Teile einer Stunde, eines Tages und eines Jahres. Tippe auf die Karten.",
