"Площадь измеряют в квадратных единицах (см², м²), а объём — в кубических (см³, м³).": "Der Flächeninhalt wird in Quadrateinheiten (cm², m²) gemessen, das Volumen in Kubikeinheiten (cm³, m³).",
"Скобки по-разному, результат тот же — сочетательное свойство. Знак ∪ — объединение.": "Die Klammern anders gesetzt, das Ergebnis bleibt gleich — das ist das Verbindungsgesetz. Das Zeichen ∪ bedeutet Vereinigung.",
"Остаток всегда меньше делителя. Остаток 9 не меньше 7, значит, получиться не может.": "Der Rest ist immer kleiner als der Divisor. Der Rest 9 ist nicht kleiner als 7, also kann das nicht herauskommen.",
"Один велосипедист едет впереди, а второй, более быстрый, едет за ним в ту же сторону": "Ein Radfahrer fährt vorn, und der zweite, schnellere, fährt hinter ihm in dieselbe Richtung",
