"Выполнять деление многозначных чисел на 10, 100, 1 000 с остатком и проверять результат": "Die Division mehrstelliger Zahlen durch 10, 100, 1 000 mit Rest ausführen und das Ergebnis prüfen",
"Выполнять деление многозначных чисел на 10, 100, 1 000 с остатком и проверять результат": "Die Division mehrstelliger Zahlen durch 10, 100, 1 000 mit Rest ausführen und das Ergebnis prüfen",
