"Площадь одной клетки: 10 · 10 = 100 мм². Клеток 21. 21 · 100 = 2 100. Площадь 2 100 мм².": "Der Flächeninhalt eines Kästchens: 10 · 10 = 100 mm². Es sind 21 Kästchen. 21 · 100 = 2 100. Der Flächeninhalt ist 2 100 mm².",
"Площадь одной клетки: 10 · 10 = 100 мм². Клеток 21. 21 · 100 = 2 100. Площадь 2 100 мм².": "Der Flächeninhalt eines Kästchens: 10 · 10 = 100 mm². Es sind 21 Kästchen. 21 · 100 = 2 100. Der Flächeninhalt ist 2 100 mm².",
"999 меньше 1 000, поэтому такой остаток возможен. Например, 5 999 : 1 000 = 5 (ост. 999).": "999 ist kleiner als 1 000, deshalb ist so ein Rest möglich. Zum Beispiel 5 999 : 1 000 = 5 (Rest 999).",
