"Узнать, что такое миллиграмм, выражать массу в разных единицах и сравнивать значения масс": "Erfahren, was ein Milligramm ist, die Masse in verschiedenen Einheiten ausdrücken und Massen vergleichen",
"Последнюю цифру суммы даёт разряд единиц: 1 + 0 = 1, в единицах пишем 1. Всё число: 81 361": "Die letzte Ziffer der Summe liefert die Einerstelle: 1 + 0 = 1, bei den Einern schreiben wir 1. Die ganze Zahl: 81 361",
"Последнюю цифру суммы даёт разряд единиц: 1 + 0 = 1, в единицах пишем 1. Всё число: 81 361": "Die letzte Ziffer der Summe liefert die Einerstelle: 1 + 0 = 1, bei den Einern schreiben wir 1. Die ganze Zahl: 81 361",
"Первая часть: 80 · 4 = 320 км. Вторая часть: 40 · 2 = 80 км. Весь путь: 320 + 80 = 400 км.": "Erster Teil: 80 · 4 = 320 km. Zweiter Teil: 40 · 2 = 80 km. Der ganze Weg: 320 + 80 = 400 km.",
"Сначала считаем кубики в одном слое: длина · ширина. Потом умножаем на число слоёв — высоту": "Zuerst zählen wir die Würfel in einer Schicht: Länge · Breite. Dann multiplizieren wir mit der Anzahl der Schichten — der Höhe",
"Площадь всего прямоугольника: 15 · 6 = 90 м². Площадь выреза: 4 · 2 = 8 м². 90 − 8 = 82 м².": "Flächeninhalt des ganzen Rechtecks: 15 · 6 = 90 m². Flächeninhalt des Ausschnitts: 4 · 2 = 8 m². 90 − 8 = 82 m².",
"В магазине предлагают: 750 тг за 3 кг мандаринов или 850 тг за 5 кг. Где мандарины дешевле?": "Im Geschäft gibt es: 750 Tenge für 3 kg Mandarinen oder 850 Tenge für 5 kg. Wo sind die Mandarinen billiger?",
"В магазине предлагают: 750 тг за 3 кг мандаринов или 850 тг за 5 кг. Где мандарины дешевле?": "Im Geschäft gibt es: 750 Tenge für 3 kg Mandarinen oder 850 Tenge für 5 kg. Wo sind die Mandarinen billiger?",
"Если из суммы вычесть одно слагаемое, получится другое. Например, 12 + 5 = 17, а 17 − 5 = 12": "Zieht man von der Summe einen Summanden ab, erhält man den anderen. Zum Beispiel 12 + 5 = 17, und 17 − 5 = 12",
"Объединение: { 2; 4; 6; 8; 10; 12 }. Общие элементы 4 и 8 считаем один раз, поэтому всего 6.": "Vereinigung: { 2; 4; 6; 8; 10; 12 }. Die gemeinsamen Elemente 4 und 8 zählen wir nur einmal, deshalb sind es insgesamt 6.",
"Площадь листа: 14 · 10 = 140 м². Площадь выреза: 7 · 5 = 35 м². Осталось: 140 − 35 = 105 м².": "Flächeninhalt des Blattes: 14 · 10 = 140 m². Flächeninhalt des Ausschnitts: 7 · 5 = 35 m². Übrig bleibt: 140 − 35 = 105 m².",
"Каждый скрипач — музыкант, значит, всё множество скрипачей лежит внутри множества музыкантов.": "Jeder Geiger ist ein Musiker, also liegt die ganze Menge der Geiger innerhalb der Menge der Musiker.",
"В 1 километре 1 000 метров, в 1 часе 60 минут. Поэтому 36 км/ч = 36 · 1 000 : 60 = 600 м/мин.": "In 1 Kilometer sind 1 000 Meter, in 1 Stunde 60 Minuten. Deshalb 36 km/h = 36 · 1 000 : 60 = 600 m/min.",
"В 1 километре 1 000 метров, в 1 часе 60 минут. Поэтому 36 км/ч = 36 · 1 000 : 60 = 600 м/мин.": "In 1 Kilometer sind 1 000 Meter, in 1 Stunde 60 Minuten. Deshalb 36 km/h = 36 · 1 000 : 60 = 600 m/min.",
