"От школы до дома 1 360 м. Тимур идёт со скоростью 80 м/мин. За сколько минут он дойдёт до дома?": "Von der Schule bis nach Hause sind es 1 360 m. Timur geht mit 80 m/min. In wie vielen Minuten kommt er nach Hause?",
"От школы до дома 1 360 м. Тимур идёт со скоростью 80 м/мин. За сколько минут он дойдёт до дома?": "Von der Schule bis nach Hause sind es 1 360 m. Timur geht mit 80 m/min. In wie vielen Minuten kommt er nach Hause?",
"Тех, кто занимается и тем и другим, при сложении посчитали дважды. 18 + 12 − 7 = 23. Ответ: 23.": "Wer beides macht, wurde bei der Addition doppelt gezählt. 18 + 12 − 7 = 23. Antwort: 23.",
"Наибольшая сумма в разряде: 9 + 9 + 1 = 19. Это 1 десяток и 9 единиц, значит переносим только 1.": "Die größte Summe in einer Stelle: 9 + 9 + 1 = 19. Das sind 1 Zehner und 9 Einer, also übertragen wir nur 1.",
