"Считаем разряды справа: 7 — единицы, 0 — десятки, 2 — сотни, 5 — единицы тысяч, 8 — десятки тысяч.": "Wir zählen die Stellen von rechts: 7 — Einer, 0 — Zehner, 2 — Hunderter, 5 — Tausender, 8 — Zehntausender.",
"Если цена та же, а количество товара стало больше в 4 раза, стоимость тоже станет больше в 4 раза.": "Bleibt der Preis gleich und die Warenmenge wird 4-mal größer, werden auch die Kosten 4-mal größer.",
