"Делим по очереди: 96 : 4 = 24, 24 : 2 = 12. Если делитель увеличить в 2 раза, частное уменьшится в 2 раза.": "Wir teilen nacheinander: 96 : 4 = 24, 24 : 2 = 12. Wird der Divisor 2-mal größer, wird der Quotient 2-mal kleiner.",
"Класс миллионов — 105, класс тысяч — 300, класс единиц — 012. Нули нужны, чтобы цифры встали на свои места.": "Millionenklasse — 105, Tausenderklasse — 300, Einerklasse — 012. Die Nullen braucht man, damit die Ziffern an ihrem Platz stehen.",
"Чтобы сравнить площади, переводим их в одну единицу. Пример: 5 а и 450 м²: 5 а = 500 м², а 500 м² > 450 м².": "Um Flächeninhalte zu vergleichen, rechnen wir sie in eine Einheit um. Beispiel: 5 a und 450 m²: 5 a = 500 m², und 500 m² > 450 m².",
"На 2 делятся числа, которые оканчиваются на 0, 2, 4, 6, 8. 3 729 оканчивается на 9, значит, на 2 не делится.": "Durch 2 sind Zahlen teilbar, die auf 0, 2, 4, 6, 8 enden. 3 729 endet auf 9, also ist sie nicht durch 2 teilbar.",
