"Смотрим на цифру справа от разряда тысяч: это 3. Она меньше 5, значит разряд не меняем. Получаем 52 000.": "Wir sehen auf die Ziffer rechts von der Tausenderstelle: Das ist 3. Sie ist kleiner als 5, also ändern wir die Stelle nicht. Wir erhalten 52 000.",
