"Разность + вычитаемое = уменьшаемое: 81 239 + 9 105 = 90 344. Получилось 90 344, значит вычитание верное.": "Differenz + Subtrahend = Minuend: 81 239 + 9 105 = 90 344. Es kam 90 344 heraus, also stimmt die Subtraktion.",
