"Если число оканчивается на 0, оно делится на 2 и на 5. Например, 34 560 : 2 = 17 280 и 34 560 : 5 = 6 912.": "Wenn eine Zahl auf 0 endet, ist sie durch 2 und durch 5 teilbar. Zum Beispiel 34 560 : 2 = 17 280 und 34 560 : 5 = 6 912.",
