"Уменьшаемое = разность + вычитаемое: 47 042 + 8 890 = 55 932. Так мы проверяем вычитание сложением": "Minuend = Differenz + Subtrahend: 47 042 + 8 890 = 55 932. So prüfen wir die Subtraktion mit der Addition",
