"A = { 1; 2; 3; 6; 9; 12 }, B = { 2; 3; 4; 10; 12 }. Найди объединение A ∪ B.": "A = { 1; 2; 3; 6; 9; 12 }, B = { 2; 3; 4; 10; 12 }. Finde die Vereinigung A ∪ B.",
"Сначала действие в скобках: 232 + 81 = 313. Потом умножаем: 313 · 6 = 1 878.": "Zuerst die Rechnung in der Klammer: 232 + 81 = 313. Dann multiplizieren wir: 313 · 6 = 1 878.",
"Сначала действие в скобках: 232 + 81 = 313. Потом умножаем: 313 · 6 = 1 878.": "Zuerst die Rechnung in der Klammer: 232 + 81 = 313. Dann multiplizieren wir: 313 · 6 = 1 878.",
"Как изменится частное, если делитель увеличить в 2 раза, а делимое не менять?": "Wie verändert sich der Quotient, wenn man den Divisor auf das 2-Fache vergrößert und den Dividenden nicht ändert?",
"Расстояние 150 км, скорость поезда 50 километров в час. Сколько часов в пути?": "Die Entfernung beträgt 150 km, die Geschwindigkeit des Zuges 50 Kilometer pro Stunde. Wie viele Stunden dauert die Fahrt?",
"A = { 4; 6; 8; 9; 12 }. Какое из множеств является подмножеством множества A?": "A = { 4; 6; 8; 9; 12 }. Welche der Mengen ist eine Teilmenge der Menge A?",
"Круги Эйлера: «делятся на 2» и «делятся на 5». Где нужно записать число 3 087?": "Euler-Kreise: «durch 2 teilbar» und «durch 5 teilbar». Wo muss man die Zahl 3 087 eintragen?",
"Круги Эйлера: «делятся на 2» и «делятся на 5». Где нужно записать число 3 087?": "Euler-Kreise: «durch 2 teilbar» und «durch 5 teilbar». Wo muss man die Zahl 3 087 eintragen?",
"Если A = { 4; 5; 7; 8; 9; 10 }, B = { 2; 3; 5; 8; 9 }, то A ∩ B = { 5; 8; 9 }.": "Wenn A = { 4; 5; 7; 8; 9; 10 }, B = { 2; 3; 5; 8; 9 }, dann ist A ∩ B = { 5; 8; 9 }.",
"Света проехала на велосипеде 800 м за 4 мин. Какую скорость записать в ответе?": "Sweta ist 800 m in 4 min mit dem Fahrrad gefahren. Welche Geschwindigkeit muss man als Antwort schreiben?",
"A = {Т, О, Б}, B = {Т, Б, К, Е}. Сколько элементов в объединении этих множеств?": "A = {Т, О, Б}, B = {Т, Б, К, Е}. Wie viele Elemente hat die Vereinigung dieser Mengen?",
"Размеры контейнера: 20 дм × 10 дм × 10 дм. Найди его объём в кубических метрах.": "Maße des Containers: 20 dm × 10 dm × 10 dm. Finde sein Volumen in Kubikmetern.",
