"18 км = 18 000 м, 1 ч = 60 мин. 18 000 : 60 = 300. Значит, 18 км/ч = 300 м/мин.": "18 km = 18 000 m, 1 h = 60 min. 18 000 : 60 = 300. Also 18 km/h = 300 m/min.",
"18 км = 18 000 м, 1 ч = 60 мин. 18 000 : 60 = 300. Значит, 18 км/ч = 300 м/мин.": "18 km = 18 000 m, 1 h = 60 min. 18 000 : 60 = 300. Also 18 km/h = 300 m/min.",
"Каждую минуту расстояние сокращается на 70 − 55 = 15 м. За 4 мин: 15 · 4 = 60 м.": "Jede Minute verkürzt sich die Entfernung um 70 − 55 = 15 m. In 4 min: 15 · 4 = 60 m.",
"Не все элементы {П, Т, О, Д} есть в {Д, Т, Е, Б}: есть «лишние» элементы {П, О}.": "Nicht alle Elemente von {П, Т, О, Д} sind in {Д, Т, Е, Б}: Es gibt «überzählige» Elemente {П, О}.",
"Проверим умножением: 6 040 · 8 = 48 320. В остальных равенствах частное неверное.": "Wir prüfen mit der Multiplikation: 6 040 · 8 = 48 320. In den anderen Gleichungen ist der Quotient falsch.",
"Проверим умножением: 6 040 · 8 = 48 320. В остальных равенствах частное неверное.": "Wir prüfen mit der Multiplikation: 6 040 · 8 = 48 320. In den anderen Gleichungen ist der Quotient falsch.",
"Сначала читаем класс тысяч: «четыреста пять тысяч», потом класс единиц: «сто два».": "Zuerst lesen wir die Tausenderklasse: «vierhundertfünf Tausend», dann die Einerklasse: «hundertzwei».",
"Сначала умножение: 3 · 4 = 12. Потом слева направо: 762 + 12 = 774, 774 − 8 = 766.": "Zuerst die Multiplikation: 3 · 4 = 12. Dann von links nach rechts: 762 + 12 = 774, 774 − 8 = 766.",
"448 + 242 = 690, потом 690 + 60 = 750. Так считать проще: получилось круглое число.": "448 + 242 = 690, dann 690 + 60 = 750. So rechnet es sich leichter: Es ergibt sich eine runde Zahl.",
"Не все элементы {К, С, Е, М} есть в {Б, Е, П, Н}: есть «лишние» элементы {К, С, М}.": "Nicht alle Elemente von {К, С, Е, М} sind in {Б, Е, П, Н}: Es gibt «überzählige» Elemente {К, С, М}.",
"Во всех разрядах цифра уменьшаемого не меньше цифры вычитаемого, занимать не нужно.": "In allen Stellen ist die Ziffer des Minuenden nicht kleiner als die Ziffer des Subtrahenden, man muss nicht borgen.",
"В любом классе по 3 разряда: единицы миллионов, десятки миллионов и сотни миллионов.": "In jeder Klasse gibt es 3 Stellen: Einermillionen, Zehnmillionen und Hundertmillionen.",
"1 кг сахара стоит 580 тг, 1 кг муки — 160 тг. Сколько стоят 3 кг сахара и 2 кг муки?": "1 kg Zucker kostet 580 Tenge, 1 kg Mehl — 160 Tenge. Wie viel kosten 3 kg Zucker und 2 kg Mehl?",
