"1 кг сахара стоит 520 тг, 1 кг муки — 300 тг. Сколько стоят 5 кг сахара и 2 кг муки?": "1 kg Zucker kostet 520 Tenge, 1 kg Mehl — 300 Tenge. Wie viel kosten 5 kg Zucker und 2 kg Mehl?",
