"Скорость сближения при движении в одну сторону: 80 − 60 = 20 м/мин. 100 : 20 = 5 мин.": "Annäherungsgeschwindigkeit bei Bewegung in dieselbe Richtung: 80 − 60 = 20 m/min. 100 : 20 = 5 min.",
"Многозначное число раскладываем на разрядные слагаемые: 4 372 = 4 000 + 300 + 70 + 2.": "Eine mehrstellige Zahl zerlegen wir in Stellenwertsummanden: 4 372 = 4 000 + 300 + 70 + 2.",
"Многозначное число раскладываем на разрядные слагаемые: 4 372 = 4 000 + 300 + 70 + 2.": "Eine mehrstellige Zahl zerlegen wir in Stellenwertsummanden: 4 372 = 4 000 + 300 + 70 + 2.",
"Остаток всегда меньше делителя. 15 не меньше 10, значит, такого остатка быть не может.": "Der Rest ist immer kleiner als der Divisor. 15 ist nicht kleiner als 10, also kann es einen solchen Rest nicht geben.",
"Складываем единицы с единицами, потом десятки с десятками и так далее — справа налево.": "Wir addieren Einer mit Einern, dann Zehner mit Zehnern und so weiter — von rechts nach links.",
"От Алматы до Астаны примерно 1 213 км. Сколько это километров, если округлить до сотен?": "Von Almaty bis Astana sind es etwa 1 213 km. Wie viele Kilometer sind das, wenn man auf Hunderter rundet?",
"Площадь пола — это a · b. Тогда V = (a · b) · c = 20 · 5 = 100. Объём комнаты — 100 м³.": "Die Bodenfläche ist a · b. Dann ist V = (a · b) · c = 20 · 5 = 100. Das Volumen des Zimmers beträgt 100 m³.",
"Площадь пола — это a · b. Тогда V = (a · b) · c = 20 · 5 = 100. Объём комнаты — 100 м³.": "Die Bodenfläche ist a · b. Dann ist V = (a · b) · c = 20 · 5 = 100. Das Volumen des Zimmers beträgt 100 m³.",
