"На 4 спортивных клуба поровну разделили 800 000 тенге. Сколько тенге получил каждый клуб?": "800 000 Tenge wurden gleichmäßig auf 4 Sportvereine verteilt. Wie viele Tenge hat jeder Verein bekommen?",
"Если длину увеличить в 2 раза, а ширину уменьшить в 2 раза, объём станет больше в 2 раза.": "Wenn man die Länge auf das 2-Fache vergrößert und die Breite 2-mal verkleinert, wird das Volumen 2-mal größer.",
"Количество товара не меняется. Как изменится стоимость, если цена станет меньше в 2 раза?": "Die Menge der Ware ändert sich nicht. Wie verändern sich die Kosten, wenn der Preis 2-mal kleiner wird?",
"Если оба едут в одну сторону с одинаковой скоростью, то расстояние между ними не меняется.": "Wenn beide in dieselbe Richtung mit gleicher Geschwindigkeit fahren, ändert sich die Entfernung zwischen ihnen nicht.",
"В таблице известны измерения a = 11 м, b = 7 м и объём V = 308 м³. Чему равно измерение c?": "In der Tabelle sind die Maße a = 11 m, b = 7 m und das Volumen V = 308 m³ bekannt. Wie groß ist das Maß c?",
"В таблице известны измерения a = 11 м, b = 7 м и объём V = 308 м³. Чему равно измерение c?": "In der Tabelle sind die Maße a = 11 m, b = 7 m und das Volumen V = 308 m³ bekannt. Wie groß ist das Maß c?",
