"Рубль (₽) — валюта России. 1 руб. = 100 коп. Например, 3 руб. 20 коп. = 300 + 20 = 320 коп.": "Der Rubel (₽) ist die Währung Russlands. 1 Rubel = 100 Kop. Zum Beispiel 3 Rubel 20 Kop. = 300 + 20 = 320 Kop.",
"Площадка составлена из двух прямоугольников 11 м × 3 м и 5 м × 5 м. Найди площадь площадки.": "Der Platz besteht aus zwei Rechtecken 11 m × 3 m und 5 m × 5 m. Finde die Fläche des Platzes.",
"Площадка составлена из двух прямоугольников 11 м × 3 м и 5 м × 5 м. Найди площадь площадки.": "Der Platz besteht aus zwei Rechtecken 11 m × 3 m und 5 m × 5 m. Finde die Fläche des Platzes.",
"Если денег в мелких единицах не хватает, можно занять 1 рубль и превратить его в 100 копеек.": "Wenn das Geld in kleinen Einheiten nicht reicht, kann man 1 Rubel borgen und in 100 Kopeken umwandeln.",
"1 дм³ = 1 000 см³: в кубике с ребром 10 см помещается 10 · 10 · 10 = 1 000 кубиков по 1 см³.": "1 dm³ = 1 000 cm³: In einen Würfel mit der Kante 10 cm passen 10 · 10 · 10 = 1 000 Würfelchen zu je 1 cm³.",
"Нули занять не могут. Занимаем у ближайшей цифры, не равной нулю, а нули становятся девятками": "Nullen können nicht borgen. Wir borgen von der nächsten Ziffer, die nicht Null ist, und die Nullen werden zu Neunen",
"Последнюю цифру суммы даёт разряд единиц: 9 + 4 = 13, в единицах пишем 3. Всё число: 134 163.": "Die letzte Ziffer der Summe liefert die Stelle der Einer: 9 + 4 = 13, bei den Einern schreiben wir 3. Die ganze Zahl: 134 163.",
"Последнюю цифру суммы даёт разряд единиц: 9 + 4 = 13, в единицах пишем 3. Всё число: 134 163.": "Die letzte Ziffer der Summe liefert die Stelle der Einer: 9 + 4 = 13, bei den Einern schreiben wir 3. Die ganze Zahl: 134 163.",
"Если к разности прибавить вычитаемое, получится уменьшаемое. Например, 9 − 4 = 5, а 5 + 4 = 9.": "Wenn man zur Differenz den Subtrahenden addiert, erhält man den Minuenden. Zum Beispiel 9 − 4 = 5, und 5 + 4 = 9.",
"Наибольшая сумма в разряде: 9 + 9 + 1 = 19. Это 1 десяток и 9 единиц, значит переносим только 1": "Die größte Summe in einer Stelle: 9 + 9 + 1 = 19. Das sind 1 Zehner und 9 Einer, also übertragen wir nur 1",
"Проверяем умножением: скорость · время = расстояние. Было 70 км/ч, и 70 · 3 = 210 км — совпало.": "Wir prüfen mit der Multiplikation: Geschwindigkeit · Zeit = Entfernung. Es waren 70 km/h, und 70 · 3 = 210 km — stimmt überein.",
"Конфеты фасуют в пакеты по 5 штук. Какое количество конфет можно разложить в пакеты без остатка?": "Bonbons werden in Tüten zu je 5 Stück abgepackt. Welche Anzahl Bonbons kann man ohne Rest in Tüten packen?",
"Каждый час расстояние растёт на 90 + 60 = 150 км. 150 · 4 = 600. Через 4 часа между ними 600 км.": "Jede Stunde wächst die Entfernung um 90 + 60 = 150 km. 150 · 4 = 600. Nach 4 Stunden sind es zwischen ihnen 600 km.",
