"Фигура А: 5 · 5 + 5 · 2 = 35 м². Фигура Б: 12 · 7 − 3 · 2 = 78 м². Больше у фигуры Б.": "Figur А: 5 · 5 + 5 · 2 = 35 m². Figur Б: 12 · 7 − 3 · 2 = 78 m². Größer ist Figur Б.",
