"Сначала крупные единицы заменяем мелкими: 3 а = 300 м². Потом считаем: 300 − 200 = 100 м²": "Zuerst ersetzen wir große Einheiten durch kleine: 3 a = 300 m². Dann rechnen wir: 300 − 200 = 100 m²",
