"Умножаем разряд за разрядом: 4 · 2 = 8, 2 · 2 = 4, 1 · 2 = 2, 3 · 2 = 6, 2 · 2 = 4. Получаем 46 248.": "Wir multiplizieren Stelle für Stelle: 4 · 2 = 8, 2 · 2 = 4, 1 · 2 = 2, 3 · 2 = 6, 2 · 2 = 4. Es ergibt 46 248.",
