"Пересечение не зависит от порядка множеств (переместительное свойство): B ∩ A = A ∩ B.": "Die Schnittmenge hängt nicht von der Reihenfolge der Mengen ab (Kommutativgesetz): B ∩ A = A ∩ B.",
"1 а = 100 м², 1 га = 10 000 м², 1 га = 100 а. Например, 5 га = 5 · 10 000 = 50 000 м².": "1 a = 100 m², 1 ha = 10 000 m², 1 ha = 100 a. Zum Beispiel 5 ha = 5 · 10 000 = 50 000 m².",
"1 а = 100 м², 1 га = 10 000 м², 1 га = 100 а. Например, 5 га = 5 · 10 000 = 50 000 м².": "1 a = 100 m², 1 ha = 10 000 m², 1 ha = 100 a. Zum Beispiel 5 ha = 5 · 10 000 = 50 000 m².",
