"Цена за 1 кг: 600 : 2 = 300 и 1 320 : 4 = 330. Во втором случае цена больше, а не ниже.": "Preis für 1 kg: 600 : 2 = 300 und 1 320 : 4 = 330. Im zweiten Fall ist der Preis höher, nicht niedriger.",
"Какое наименьшее из чисел 2 499, 2 500 и 2 400 при округлении до тысяч становится 3 000?": "Welche der Zahlen 2 499, 2 500 und 2 400 ist die kleinste, die beim Runden auf Tausender 3 000 wird?",
"Остаток всегда меньше делителя. 150 не меньше 100, значит, такого остатка быть не может.": "Der Rest ist immer kleiner als der Divisor. 150 ist nicht kleiner als 100, also kann es einen solchen Rest nicht geben.",
"В выражении без скобок сначала выполняют умножение и деление, потом сложение и вычитание.": "In einem Ausdruck ohne Klammern rechnet man zuerst Multiplikation und Division, dann Addition und Subtraktion.",
"Читать и записывать числа в пределах миллиарда и записывать их суммой разрядных слагаемых": "Zahlen bis zu einer Milliarde lesen und schreiben und als Summe der Stellenwerte schreiben",
"В цистерне было 12 500 л воды. За день 4 раза вывезли по 2 500 л. Сколько литров осталось?": "In einem Tank waren 12 500 l Wasser. An einem Tag wurden 4-mal je 2 500 l abtransportiert. Wie viele Liter blieben übrig?",
"Ребро нужно умножить на себя три раза: 4 · 4 · 4 = 64 см³. А 16 — это площадь грани в см².": "Die Kante muss man dreimal mit sich selbst multiplizieren: 4 · 4 · 4 = 64 cm³. Und 16 ist die Fläche einer Seitenfläche in cm².",
"Сколько цифр в числе «двадцать шесть миллионов восемьсот девяносто тысяч девятьсот девять»?": "Wie viele Ziffern hat die Zahl „sechsundzwanzig Millionen achthundertneunzigtausendneunhundertneun“?",
"Фигура составлена из трёх прямоугольников: 8 м × 2 м, 6 м × 5 м и 7 м × 3 м. Найди площадь.": "Die Figur besteht aus drei Rechtecken: 8 m × 2 m, 6 m × 5 m und 7 m × 3 m. Finde die Fläche.",
"Фигура составлена из трёх прямоугольников: 8 м × 2 м, 6 м × 5 м и 7 м × 3 м. Найди площадь.": "Die Figur besteht aus drei Rechtecken: 8 m × 2 m, 6 m × 5 m und 7 m × 3 m. Finde die Fläche.",
"Находить время и расстояние по формулам t = S : v и S = v · t и переводить единицы скорости": "Zeit und Entfernung mit den Formeln t = S : v und S = v · t finden und Geschwindigkeitseinheiten umrechnen",
"Сначала читаем класс миллионов со словом «миллионов», потом класс тысяч, потом класс единиц.": "Zuerst lesen wir die Millionenklasse mit dem Wort „Millionen“, dann die Tausenderklasse, dann die Einerklasse.",
"Проверка: 192 · 1 000 + 215 = 192 215 подтверждает деление 192 215 : 1 000 = 192 (ост. 215).": "Probe: 192 · 1 000 + 215 = 192 215 bestätigt die Division 192 215 : 1 000 = 192 (Rest 215).",
"Проверка: 192 · 1 000 + 215 = 192 215 подтверждает деление 192 215 : 1 000 = 192 (ост. 215).": "Probe: 192 · 1 000 + 215 = 192 215 bestätigt die Division 192 215 : 1 000 = 192 (Rest 215).",
"Объединение — все элементы обоих множеств, общие записываем один раз: {Д, П, К, Н, И, Л, Р}.": "Vereinigung — alle Elemente beider Mengen, gemeinsame schreiben wir einmal: {D, P, K, N, I, L, R}.",
"Скорости 40 км/ч и 50 км/ч, расстояние 180 км. Навстречу друг другу они встретятся через 2 ч.": "Geschwindigkeiten 40 km/h und 50 km/h, Entfernung 180 km. Wenn sie aufeinander zufahren, treffen sie sich nach 2 h.",
"Какое наименьшее число надо прибавить к 51 661, чтобы получилось число, которое делится на 5?": "Welche ist die kleinste Zahl, die man zu 51 661 addieren muss, damit eine durch 5 teilbare Zahl herauskommt?",
