"Как найти скорость удаления, если тела движутся в противоположные стороны?": "Wie findet man die Geschwindigkeit, mit der sich die Körper voneinander entfernen, wenn sie sich in entgegengesetzte Richtungen bewegen?",
"Расстояние между ними сокращается, они выехали из разных мест друг к другу": "Der Abstand zwischen ihnen wird kleiner, sie sind von verschiedenen Orten aufeinander zu gefahren",
"8 · 7 = 56. Единицы пишем под чертой, десятки переносим в следующий разряд.": "8 · 7 = 56. Die Einer schreiben wir unter den Strich, die Zehner übertragen wir in die nächste Stelle.",
"Они удаляются друг от друга обоими движениями, поэтому скорости складываем.": "Sie entfernen sich mit beiden Bewegungen voneinander, deshalb addieren wir die Geschwindigkeiten.",
