"Множества «Овощи» и «Фрукты» не имеют общих элементов. Как нарисовать круги?": "Die Mengen „Gemüse“ und „Obst“ haben keine gemeinsamen Elemente. Wie zeichnet man die Kreise?",
"На складе 90 415 кг муки в мешках по 10 кг. Сколько полных мешков получится?": "Im Lager sind 90 415 kg Mehl in Säcken zu je 10 kg. Wie viele volle Säcke ergibt das?",
