"Сравни цифры по разрядам справа налево. Если сверху цифра меньше, нужен заём.": "Vergleiche die Ziffern stellenweise von rechts nach links. Ist die obere Ziffer kleiner, muss man borgen.",
"Скорость измеряют в единицах расстояния за единицу времени: км/ч, м/мин, м/с.": "Die Geschwindigkeit misst man in Entfernungseinheiten pro Zeiteinheit: km/h, m/min, m/s.",
"Объём коробки 36 см³. Длина коробки 3 см, ширина 4 см. Какова высота коробки?": "Das Volumen der Schachtel ist 36 cm³. Die Länge der Schachtel ist 3 cm, die Breite 4 cm. Wie hoch ist die Schachtel?",
