"Цифры делим на классы по три справа налево: 345 — класс тысяч, 678 — класс единиц. Всего 2 класса.": "Wir teilen die Ziffern von rechts nach links in Klassen zu je drei: 345 — Tausenderklasse, 678 — Einerklasse. Insgesamt 2 Klassen.",
